function ttLoadWorkOrder(PDO $pdo,int $id,int $railroadId):array{$stmt=$pdo->prepare('SELECT sl.*,a.assignment_number,a.title_snapshot,a.operating_pattern,a.status assignment_status,a.operating_base_industry_id,a.starting_track,a.start_method,a.crew_name,a.dispatcher_crew_message,a.end_plan,a.end_industry_id,a.end_track,a.predecessor_assignment_id,s.status session_status,s.session_number,s.session_name,s.operating_date,i.industry_name base_name FROM operation_switch_lists sl JOIN operation_assignments a ON a.id=sl.assignment_id AND a.railroad_id=sl.railroad_id JOIN operating_sessions s ON s.id=sl.session_id AND s.railroad_id=sl.railroad_id LEFT JOIN industries i ON i.id=a.operating_base_industry_id WHERE sl.id=? AND sl.railroad_id=?');$stmt->execute([$id,$railroadId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row){http_response_code(404);die('Work order not found.');}return$row;}
$list=ttLoadWorkOrder($pdo,$id,$railroadId);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{ttOperationsRequireCsrf();$action=(string)($_POST['action']??'');
  if($action==='approve'){
   $pdo->beginTransaction();$sessionLock=$pdo->prepare('SELECT status FROM operating_sessions WHERE id=? AND railroad_id=? FOR UPDATE');$sessionLock->execute([(int)$list['session_id'],$railroadId]);$sessionStatus=$sessionLock->fetchColumn();$assignmentLock=$pdo->prepare('SELECT * FROM operation_assignments WHERE id=? AND railroad_id=? FOR UPDATE');$assignmentLock->execute([(int)$list['assignment_id'],$railroadId]);$lockedAssignment=$assignmentLock->fetch(PDO::FETCH_ASSOC);if(!$lockedAssignment)throw new RuntimeException('Assignment not found.');$lockedAssignment['session_status']=(string)$sessionStatus;$summary=ttSwitchListRevisionSummary($pdo,(int)$list['assignment_id'],$railroadId,true);$lockedList=null;foreach($summary['rows']as$row)if((int)$row['id']===$id){$lockedList=$row;break;}if(!$lockedList||!ttSwitchListIsApprovable($lockedList,$lockedAssignment,$summary)){http_response_code(409);throw new RuntimeException('This switch-list draft is stale, superseded, or no longer safe to approve. Open the latest current revision.');}
   $stmt=$pdo->prepare("UPDATE operation_switch_lists SET status='approved',approved_at=NOW(),approved_by_user_id=? WHERE id=? AND railroad_id=? AND status='draft'");$stmt->execute([(int)$_SESSION['user_id'],$id,$railroadId]);if($stmt->rowCount()!==1){http_response_code(409);throw new RuntimeException('This switch-list draft changed before approval.');}$pdo->prepare("UPDATE operation_assignments SET status=IF(predecessor_assignment_id IS NULL,'ready','waiting'),approved_at=NOW() WHERE id=? AND railroad_id=?")->execute([(int)$list['assignment_id'],$railroadId]);if($list['start_method']==='prepared_cut')$pdo->prepare("UPDATE prepared_cuts SET status='assigned' WHERE id=(SELECT prepared_cut_id FROM operation_assignments WHERE id=?) AND status='ready'")->execute([(int)$list['assignment_id']]);$pdo->commit();$message='Revision approved and frozen.';
  }
  elseif($action==='abort'){$pdo->beginTransaction();$note=substr(trim((string)($_POST['abort_note']??'')),0,5000);$lock=$pdo->prepare('SELECT a.status assignment_status,s.status session_status FROM operation_assignments a JOIN operating_sessions s ON s.id=a.session_id AND s.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=? FOR UPDATE');$lock->execute([(int)$list['assignment_id'],$railroadId]);$state=$lock->fetch(PDO::FETCH_ASSOC);if(!$state||$state['session_status']!=='in_progress'||!in_array($state['assignment_status'],['ready','waiting','in_progress','needs_review'],true))throw new RuntimeException('An assignment can only be aborted after its operating session starts and before the assignment is completed.');$pdo->prepare("UPDATE operation_switch_lists SET status='cancelled',cancelled_at=NOW(),notes=CONCAT_WS(' ',NULLIF(TRIM(COALESCE(notes,'')),''),NULLIF(?,'')) WHERE id=? AND railroad_id=? AND status IN('draft','approved','in_progress','needs_review')")->execute([$note,$id,$railroadId]);$pdo->prepare("UPDATE operation_assignments SET status='aborted',cancelled_at=NOW() WHERE id=? AND railroad_id=?")->execute([(int)$list['assignment_id'],$railroadId]);$pdo->prepare("UPDATE prepared_cuts SET status='released' WHERE id=(SELECT prepared_cut_id FROM operation_assignments WHERE id=?) AND status IN('assigned','in_use')")->execute([(int)$list['assignment_id']]);$pdo->commit();$message='Assignment aborted. No equipment locations changed.';}
  elseif($action==='complete'){if(!$repairQueueEnabled&&in_array('bad_order',(array)($_POST['reason']??[]),true))throw new RuntimeException('Repair Queue is disabled for this railroad.');$completion=ttCompleteWorkOrderLoadNeutral($pdo,$list,$railroadId,$_POST,(int)$_SESSION['user_id']);$message='Work order completed: '.$completion['moved_as_planned'].' moved as planned'.($completion['moved_different']?', '.$completion['moved_different'].' moved to a different location':'').', '.$completion['not_moved'].' not moved. Load status remains unchanged until owner review.';}
  else throw new RuntimeException('Invalid work-order action.');$list=ttLoadWorkOrder($pdo,$id,$railroadId);
 }catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$stmt=$pdo->prepare('SELECT m.*,oi.industry_name actual_industry_name FROM operation_switch_list_moves m LEFT JOIN industries oi ON oi.id=m.actual_industry_id WHERE m.switch_list_id=? AND m.railroad_id=? ORDER BY m.sequence_number');$stmt->execute([$id,$railroadId]);$moves=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare('SELECT e.reporting_marks,e.road_number,e.photo_filename FROM operation_assignment_locomotives al JOIN equipment e ON e.id=al.equipment_id AND e.railroad_id=? WHERE al.assignment_id=? ORDER BY al.position');$stmt->execute([$railroadId,(int)$list['assignment_id']]);$locomotives=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? AND active=1 ORDER BY industry_name');$stmt->execute([$railroadId]);$industries=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare('SELECT id,revision_number,status FROM operation_switch_lists WHERE assignment_id=? AND railroad_id=? ORDER BY revision_number DESC');$stmt->execute([(int)$list['assignment_id'],$railroadId]);$revisions=$stmt->fetchAll(PDO::FETCH_ASSOC);
$revisionSummary=ttSwitchListRevisionSummary($pdo,(int)$list['assignment_id'],$railroadId);$approvalAssignment=['status'=>$list['assignment_status'],'session_status'=>$list['session_status'],'start_method'=>$list['start_method'],'end_plan'=>$list['end_plan']];$canApprove=ttSwitchListIsApprovable($list,$approvalAssignment,$revisionSummary);$closeout=$list['session_status']==='in_progress'&&in_array($list['assignment_status'],['ready','in_progress','needs_review'],true)&&in_array($list['status'],['approved','in_progress','needs_review'],true);$canAbort=$list['session_status']==='in_progress'&&in_array($list['assignment_status'],['ready','waiting','in_progress','needs_review'],true)&&in_array($list['status'],['draft','approved','in_progress','needs_review'],true);$columnCount=$closeout?8:7;$plannedMoveCount=count(array_filter($moves,static fn($move)=>!empty($move['equipment_id'])));$posted=$error!==''?$_POST:[];
