 <?php if($closeout):?><?php if($move['equipment_id']):?><?php $moveKey=(string)$move['id'];$postedOutcome=(string)($posted['exception_outcome'][$moveKey]??'');$postedReason=(string)($posted['reason'][$moveKey]??'');$postedDestination=(int)($posted['actual_industry_id'][$moveKey]??$move['destination_industry_id']);$postedTrack=(string)($posted['actual_track'][$moveKey]??$move['destination_track']);$postedNotes=(string)($posted['exception_notes'][$moveKey]??'');?><td><details class="tt-move-exception" <?=$postedOutcome!==''?'open':''?>><summary class="btn btn-sm btn-outline-warning">Add Exception</summary><div class="tt-exception-fields mt-2"><select class="form-select form-select-sm tt-exception-outcome" name="exception_outcome[<?=(int)$move['id']?>]"><option value="" <?=$postedOutcome===''?'selected':''?>>Moved as planned</option><option value="not_moved" <?=$postedOutcome==='not_moved'?'selected':''?>>Not Moved</option><option value="moved_elsewhere" <?=$postedOutcome==='moved_elsewhere'?'selected':''?>>Moved to a Different Location</option></select><div class="tt-not-moved-fields mt-2" <?=$postedOutcome==='not_moved'?'':'hidden'?>> <label class="form-label small">Exception reason</label><select class="form-select form-select-sm" name="reason[<?=(int)$move['id']?>]"><option value="">Choose reason</option><?php foreach($exceptionReasons as$v=>$label):?><option value="<?=$v?>" <?=$postedReason===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="tt-different-location-fields mt-2" <?=$postedOutcome==='moved_elsewhere'?'':'hidden'?>> <label class="form-label small">Actual destination</label><select class="form-select form-select-sm" name="actual_industry_id[<?=(int)$move['id']?>]"><option value="">Choose destination</option><?php foreach($industries as$industry):?><option value="<?=(int)$industry['id']?>" <?=$postedDestination===(int)$industry['id']?'selected':''?>><?=ttHtml($industry['industry_name'])?></option><?php endforeach;?></select><input class="form-control form-control-sm mt-1" name="actual_track[<?=(int)$move['id']?>]" value="<?=ttHtml($postedTrack)?>" placeholder="Actual Track / Spot (optional)"></div><div class="tt-exception-notes mt-2" <?=$postedOutcome===''?'hidden':''?>><label class="form-label small">Exception notes</label><input class="form-control form-control-sm" name="exception_notes[<?=(int)$move['id']?>]" value="<?=ttHtml($postedNotes)?>" placeholder="Explain the exception"></div></div></details></td><?php else:?><td></td><?php endif;?><?php endif;?></tr><?php endif;?>
