</section></div><div class="tt-lightbox" id="photoLightbox" role="dialog" aria-modal="true" aria-label="Car photo"><button type="button" aria-label="Close">×</button><img alt=""></div><script>const token=<?=json_encode(ttOperationsCsrfToken())?>;document.querySelectorAll('.tt-progress-check').forEach(c=>c.addEventListener('change',async()=>{const body=new URLSearchParams({csrf_token:token,move_id:c.dataset.moveId,complete:c.checked?'1':'0'});const r=await fetch('progress.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok){c.checked=!c.checked;alert((await r.json()).error||'Unable to save progress');}}));document.querySelectorAll('.tt-exception-outcome').forEach(select=>{const fields=select.closest('.tt-exception-fields'),sync=()=>{const value=select.value;fields.querySelector('.tt-not-moved-fields').hidden=value!=='not_moved';fields.querySelector('.tt-different-location-fields').hidden=value!=='moved_elsewhere';fields.querySelector('.tt-exception-notes').hidden=value==='';};select.addEventListener('change',sync);sync();});const closeoutForm=document.getElementById('closeoutForm');if(closeoutForm)closeoutForm.addEventListener('submit',event=>{if(event.submitter?.value!=='complete')return;const exceptions=[...closeoutForm.querySelectorAll('.tt-exception-outcome')].filter(select=>select.value!=='').length;const moves=Number(closeoutForm.dataset.plannedMoves||0);if(!confirm(`Complete this work order?\n${moves} planned moves will be applied.\n${exceptions} exception${exceptions===1?'':'s'} will be recorded.`))event.preventDefault();});const box=document.getElementById('photoLightbox'),img=box.querySelector('img'),close=()=>{box.classList.remove('is-open');};document.querySelectorAll('.tt-photo-button').forEach(b=>b.addEventListener('click',()=>{img.src=b.dataset.src;img.alt=b.dataset.alt;box.classList.add('is-open');box.querySelector('button').focus();}));box.querySelector('button').addEventListener('click',close);box.addEventListener('click',e=>{if(e.target===box)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});</script><?php include '../includes/footer.php';?>
